using System;using System.IO;using System.Text;using System.Threading;using System.Collections.Generic;using System.Diagnostics;using System.Security.Principal;using System.Security.AccessControl;using Microsoft.Win32;
internal static class UsbAdmissionWorkerQualification {
 sealed class FixtureAuthority:UsbAdmissionTransaction.INativeAuthority{public void ConsumeOwnerProof(UsbAdmissionTransaction.Request request){}public void VerifyCurrentTopology(UsbAdmissionTransaction.Request request){}}
 sealed class Clock:UsbAdmissionTransaction.IClock{public DateTime UtcNow{get{return DateTime.UtcNow;}}}
 static void Require(bool yes){if(!yes)throw new InvalidOperationException("Private backend qualification failed");}
 static void CodeRoot(){string path=UsbAdmissionWorkerBackend.CodeRoot;if(!path.EndsWith("SentinelUsbAdmissionQualification",StringComparison.Ordinal))throw new InvalidOperationException("Private root refused");if(!Directory.Exists(path)){var security=new DirectorySecurity();security.SetOwner(new SecurityIdentifier(WellKnownSidType.BuiltinAdministratorsSid,null));security.SetAccessRuleProtection(true,false);foreach(var kind in new[]{WellKnownSidType.BuiltinAdministratorsSid,WellKnownSidType.LocalSystemSid})security.AddAccessRule(new FileSystemAccessRule(new SecurityIdentifier(kind,null),FileSystemRights.FullControl,InheritanceFlags.ContainerInherit|InheritanceFlags.ObjectInherit,PropagationFlags.None,AccessControlType.Allow));security.AddAccessRule(new FileSystemAccessRule(new SecurityIdentifier(WellKnownSidType.BuiltinUsersSid,null),FileSystemRights.ReadAndExecute,InheritanceFlags.ContainerInherit|InheritanceFlags.ObjectInherit,PropagationFlags.None,AccessControlType.Allow));Directory.CreateDirectory(path,security);}}
 static UsbAdmissionTransaction.Request Request(UsbAdmissionNativeStores stores,int seconds){var before=stores.ReadCommitted();ulong generation=before==null?0:before.Generation;string sid=WindowsIdentity.GetCurrent().User.Value;var next=new UsbEnrollmentConfig.Snapshot(generation+1,sid,new[]{@"USB\SYNTHETIC\INTERFACE"},new string[0]);var policy=new List<byte>(Encoding.ASCII.GetBytes("SNTINP03"));byte[] id=Encoding.ASCII.GetBytes(@"USB\SYNTHETIC\INTERFACE");policy.Add(1);policy.Add((byte)id.Length);policy.AddRange(id);var now=DateTime.UtcNow;return new UsbAdmissionTransaction.Request(generation,next,new string('a',64),Guid.NewGuid().ToString("N"),now,now.AddSeconds(seconds),policy.ToArray());}
 [STAThread]public static int Main(string[] args){if(args.Length!=0)return 2;if(!new WindowsPrincipal(WindowsIdentity.GetCurrent()).IsInRole(WindowsBuiltInRole.Administrator))return 3;int phase=1;try{Require(UsbAdmissionWorkerBackend.TaskFinished(1)&&UsbAdmissionWorkerBackend.TaskFinished(3)&&!UsbAdmissionWorkerBackend.TaskFinished(0)&&!UsbAdmissionWorkerBackend.TaskFinished(2)&&!UsbAdmissionWorkerBackend.TaskFinished(4));var duration=Stopwatch.StartNew();CodeRoot();using(var codePin=new SentinelPolicyDirectory(UsbAdmissionWorkerBackend.CodeRoot)){if(!Directory.Exists(UsbAdmissionWorkerBackend.DirectoryPath))SentinelPolicyDirectory.Provision(UsbAdmissionWorkerBackend.DirectoryPath);using(var statePin=new SentinelPolicyDirectory(UsbAdmissionWorkerBackend.DirectoryPath)){
  if(File.Exists(Path.Combine(UsbAdmissionWorkerBackend.CodeRoot,"admission-images.txt"))){phase=81;using(var oldBackend=UsbAdmissionWorkerBackend.OpenInstalledForQualificationRecovery())using(var oldStores=new UsbAdmissionNativeStores(UsbAdmissionWorkerBackend.DirectoryPath)){if(oldStores.Read()!=null){new UsbAdmissionTransaction(oldStores,oldStores,oldBackend,new FixtureAuthority(),new Clock()).Recover();Require(oldStores.Read()==null);Console.WriteLine("PASS pending private recovery through installed pinned worker before image upgrade");}}}
 }using(var backend=UsbAdmissionWorkerBackend.CreateFromEmbeddedResources())using(var stores=new UsbAdmissionNativeStores(UsbAdmissionWorkerBackend.DirectoryPath)){
  var transaction=new UsbAdmissionTransaction(stores,stores,backend,new FixtureAuthority(),new Clock());
  if(stores.Read()!=null)transaction.Recover();
    phase=6;var paused=Request(stores,180);using(var ready=UsbAdmissionWorkerBackend.QualificationGate(paused.Nonce,"ready"))using(var release=UsbAdmissionWorkerBackend.QualificationGate(paused.Nonce,"release")){
   bool rejected=false;Exception attemptError=null;var attempt=new Thread(()=>{try{transaction.ApplyInitial(paused);}catch(Exception failure){attemptError=failure;rejected=true;}});attempt.IsBackground=true;attempt.Start();if(!ready.WaitOne(45000)){Console.WriteLine("FAIL pre-attach gate not reached; worker attempt finished="+!attempt.IsAlive+" category="+(attemptError==null?"none":UsbAdmissionWorkerBackend.FailureCategory(attemptError))+" hresult="+(attemptError==null?"none":attemptError.HResult.ToString("X8")));throw new InvalidOperationException("Private gate was not reached");}phase=62;backend.QualificationRevokeBeforeAttach(paused.JournalRecord());release.Set();phase=63;Require(attempt.Join(60000)&&rejected);phase=64;Require(backend.QualificationEmpty(paused.JournalRecord()));phase=65;transaction.Recover();phase=66;Require(stores.Read()==null);Console.WriteLine("PASS actual pre-attach producer revoked: task disabled + durable recovery phase prevented policy write");
  }
  phase=2;var first=Request(stores,180);transaction.ApplyInitial(first);Require(transaction.CurrentState==UsbAdmissionTransaction.State.PolicyActive&&stores.Read()!=null);Console.WriteLine("PASS private saved/effective apply verified");
  phase=3;transaction.Recover();Require(transaction.CurrentState==UsbAdmissionTransaction.State.Unchecked&&stores.Read()==null);Require(UsbAdmissionCleanupStage.Read(UsbAdmissionWorkerBackend.DirectoryPath,first.JournalRecord())==UsbAdmissionCleanupStage.Phase.Missing);Console.WriteLine("PASS private manual recovery and stage/task retirement");
  if(duration.Elapsed.TotalSeconds>180)throw new InvalidOperationException("Private fixture preliminary budget exceeded");
  phase=4;var second=Request(stores,120);transaction.ApplyInitial(second);Require(transaction.CurrentState==UsbAdmissionTransaction.State.PolicyActive);Console.WriteLine("PASS second nonce applied after retirement; waiting independent expiry");
  // No Recover call drives this interval: the pre-registered SYSTEM trigger must
  // restore and retire itself independently of the controller's transaction.
  while(stores.Read()!=null&&duration.Elapsed.TotalSeconds<360)Thread.Sleep(250);
  phase=5;Require(stores.Read()==null);Require(UsbAdmissionCleanupStage.Read(UsbAdmissionWorkerBackend.DirectoryPath,second.JournalRecord())==UsbAdmissionCleanupStage.Phase.Missing);backend.DemandEmptyPolicyAndNoUnownedOperations();Console.WriteLine("PASS independent private expiry, journal clear and task retirement");
 }}Console.WriteLine("PASS native private backend qualification; no DeviceInstall rules changed");return 0;}catch(Exception error){Console.WriteLine(UsbAdmissionWorkerBackend.QualificationReadCleanupFailure());Console.WriteLine("FAIL private backend phase "+phase+" category "+UsbAdmissionWorkerBackend.FailureCategory(error)+" reason "+UsbAdmissionWorkerBackend.FailureReason(error)+" hresult "+error.HResult.ToString("X8")+"; retain independent recovery for diagnosis");return 1;}}
}
